import sys
from collections import defaultdict, deque

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    N = int(data[index])
    M = int(data[index + 1])
    index += 2

    graph = defaultdict(list)
    for _ in range(N - 1):
        Ui = int(data[index])
        Vi = int(data[index + 1])
        graph[Ui].append(Vi)
        graph[Vi].append(Ui)
        index += 2

    queries = []
    for _ in range(M):
        Pi = int(data[index])
        Qi = int(data[index + 1])
        queries.append((Pi, Qi))
        index += 2

    def bfs(start, end):
        queue = deque([(start, 0)])
        visited = set([start])
        while queue:
            node, dist = queue.popleft()
            if node == end:
                return dist
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, dist + 1))
        return float('inf')

    results = []
    for Pi, Qi in queries:
        max_length = 0
        for neighbor in graph[Pi]:
            if neighbor != Qi:
                dist = bfs(neighbor, Qi)
                if dist > 0:
                    max_length = max(max_length, 2 + dist)
        results.append(max_length)

    for result in results:
        print(result)

